# name: single_example_generalization_rate
# description: Yes rate on non-example targets for sets with exactly one example; observed above null means the model under-generalises from a single example (too narrow), below means it over-generalises.
def test_statistic(df):
    ex = df["number_set"].str.split(",", expand=True).apply(pd.to_numeric).values
    t = df["target"].astype(float).values
    n = (~np.isnan(ex)).sum(axis=1)
    m = (n == 1) & ~(ex == t[:, None]).any(axis=1)
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].values[m].mean())

# name: example_target_yes_rate
# description: Yes rate on trials whose target is itself one of the shown examples; observed above null means the model under-endorses the examples themselves (too much noise/outside-concept mass), below means it over-endorses them.
def test_statistic(df):
    ex = df["number_set"].str.split(",", expand=True).apply(pd.to_numeric).values
    t = df["target"].astype(float).values
    m = (ex == t[:, None]).any(axis=1)
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].values[m].mean())

# name: late_minus_early_yes_rate
# description: Yes rate on trials in the last third of the session (trial_index >= 300) minus the first third (trial_index < 150); nonzero observed vs a near-zero null means a drift in willingness to say yes over the session that the stationary model cannot produce (positive = people become more liberal over time).
def test_statistic(df):
    ti = df["trial_index"].values
    r = df["rating"].values.astype(float)
    late, early = ti >= 300, ti < 150
    if late.sum() == 0 or early.sum() == 0:
        return 0.0
    return float(r[late].mean() - r[early].mean())
